#!/usr/bin/env python3
import cyclopts

app = cyclopts.App()

@app.default
def status():
    """Display the current status."""
    print("Status: OK")

@app.command
def start():
    """Start the service."""
    print("Service started")

@app.command
def stop():
    """Stop the service."""
    print("Service stopped")

if __name__ == "__main__":
    app()
